import { useMemo, useState } from 'react'

const actors = [
  { email: 'alice@east.test', tenant: { id: 'east', name: 'East', time_zone: 'Australia/Sydney' } },
  { email: 'bob@west.test', tenant: { id: 'west', name: 'West', time_zone: 'Australia/Perth' } },
]

const names = ['Alex Lee', 'Jamie Park', 'Morgan Chen', 'Taylor Reed', 'Avery Kim', 'Sam Rivera', 'Riley Patel', 'Casey Wong']
const initialStore = Object.fromEntries(actors.map(({ tenant }) => {
  const code = tenant.id.toUpperCase()
  const courses = [
    { id: `${tenant.id}-safety`, title: 'Safety 101' },
    { id: `${tenant.id}-privacy`, title: 'Data Privacy Basics' },
  ]
  const enrollments = names.map((name, index) => ({
    learner_id: `${tenant.id}-learner-${index + 1}`,
    learner_name: name,
    course_id: courses[index < 6 ? 0 : 1].id,
    completion_status: index === 2 || index === 6 ? 'incomplete' : 'completed',
    certificate_status: index === 0 || index === 3 || index === 7 ? 'issued' : 'none',
  }))
  const certificates = [0, 3, 7].map((index, position) => ({
    id: `${tenant.id}-certificate-${position + 1}`,
    serial_number: `${code}-${String(position + 1).padStart(6, '0')}`,
    learner: { id: enrollments[index].learner_id, name: enrollments[index].learner_name },
    course: courses[index < 6 ? 0 : 1],
    issued_at_local: tenant.id === 'east' ? '2026-01-11T00:30:00+11:00' : '2026-01-10T21:30:00+08:00',
    issued_local_date: tenant.id === 'east' ? '2026-01-11' : '2026-01-10',
    status: 'issued',
  }))
  return [tenant.id, { courses, enrollments, certificates }]
}))

const sortOptions = [
  ['issued_local_date', 'Issue date'],
  ['learner_name', 'Learner'],
  ['course_title', 'Course'],
  ['serial_number', 'Serial number'],
  ['status', 'Status'],
]

function sortValue(certificate, sortBy) {
  if (sortBy === 'learner_name') return certificate.learner.name
  if (sortBy === 'course_title') return certificate.course.title
  return certificate[sortBy]
}

function Badge({ value }) {
  return <span className={`badge badge-${value.replaceAll('_', '-')}`}>{value.replaceAll('_', ' ')}</span>
}

function localTime(value) {
  return value.replace('T', ' ').slice(0, 16)
}

function escapeCsv(value) {
  const text = String(value)
  return /[",\n\r]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

export default function App() {
  const [actorEmail, setActorEmail] = useState(actors[0].email)
  const [store, setStore] = useState(initialStore)
  const [view, setView] = useState('certificates')
  const [search, setSearch] = useState('')
  const [sortBy, setSortBy] = useState('issued_local_date')
  const [sortDir, setSortDir] = useState('desc')
  const [page, setPage] = useState(1)
  const [courseId, setCourseId] = useState('east-safety')
  const [enrollmentPage, setEnrollmentPage] = useState(1)
  const [selectedId, setSelectedId] = useState(null)
  const [confirmRevoke, setConfirmRevoke] = useState(false)
  const [outcome, setOutcome] = useState(null)
  const [notice, setNotice] = useState('')
  const [exporting, setExporting] = useState(false)
  const actor = actors.find(item => item.email === actorEmail)
  const tenant = actor.tenant
  const data = store[tenant.id]
  const selected = data.certificates.find(item => item.id === selectedId)
  const chosenCourse = data.courses.find(item => item.id === courseId)
  const pageSize = 5

  const matching = useMemo(() => data.certificates
    .filter(item => `${item.learner.name} ${item.serial_number}`.toLowerCase().includes(search.trim().toLowerCase()))
    .sort((a, b) => {
      const compared = String(sortValue(a, sortBy)).localeCompare(String(sortValue(b, sortBy)), undefined, { sensitivity: 'base' })
      return (compared * (sortDir === 'asc' ? 1 : -1)) || a.id.localeCompare(b.id)
    }), [data.certificates, search, sortBy, sortDir])

  const certificatePages = Math.ceil(matching.length / pageSize)
  const shown = matching.slice((page - 1) * pageSize, page * pageSize)
  const courseEnrollments = data.enrollments.filter(item => item.course_id === courseId)
    .sort((a, b) => a.learner_name.localeCompare(b.learner_name) || a.learner_id.localeCompare(b.learner_id))
  const enrollmentPages = Math.ceil(courseEnrollments.length / pageSize)
  const shownEnrollments = courseEnrollments.slice((enrollmentPage - 1) * pageSize, enrollmentPage * pageSize)

  function switchActor(email) {
    const next = actors.find(item => item.email === email)
    setActorEmail(email)
    setCourseId(`${next.tenant.id}-safety`)
    setSearch('')
    setPage(1)
    setEnrollmentPage(1)
    setSelectedId(null)
    setConfirmRevoke(false)
    setOutcome(null)
    setNotice('')
  }

  function issueCertificates() {
    const rows = courseEnrollments.map(row => {
      if (row.completion_status === 'incomplete') return { ...row, result: 'skipped', reason: 'incomplete' }
      if (row.certificate_status !== 'none') return { ...row, result: 'skipped', reason: 'already_certified' }
      return { ...row, result: 'issued', reason: null }
    })
    const startingNumber = data.certificates.length + 1
    const now = new Date()
    const newCertificates = rows.filter(row => row.result === 'issued').map((row, index) => {
      const number = startingNumber + index
      const localDate = new Intl.DateTimeFormat('en-CA', { timeZone: tenant.time_zone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now)
      return {
        id: `${tenant.id}-certificate-${number}`,
        serial_number: `${tenant.id.toUpperCase()}-${String(number).padStart(6, '0')}`,
        learner: { id: row.learner_id, name: row.learner_name },
        course: chosenCourse,
        issued_at_local: `${localDate}T12:00:00${tenant.id === 'east' ? '+11:00' : '+08:00'}`,
        issued_local_date: localDate,
        status: 'issued',
      }
    })
    setStore(previous => ({
      ...previous,
      [tenant.id]: {
        ...data,
        certificates: [...data.certificates, ...newCertificates],
        enrollments: data.enrollments.map(row => rows.some(result => result.learner_id === row.learner_id && result.result === 'issued') ? { ...row, certificate_status: 'issued' } : row),
      },
    }))
    setOutcome({
      operation_id: `preview-${Date.now()}`,
      status: 'completed',
      summary: { issued: newCertificates.length, skipped: rows.length - newCertificates.length, failed: 0 },
      outcomes: rows.map(row => ({ ...row, serial_number: newCertificates.find(cert => cert.learner.id === row.learner_id)?.serial_number ?? null })),
    })
  }

  function revoke() {
    if (!selected || selected.status === 'revoked') return
    setStore(previous => ({
      ...previous,
      [tenant.id]: {
        ...data,
        certificates: data.certificates.map(item => item.id === selected.id ? { ...item, status: 'revoked' } : item),
        enrollments: data.enrollments.map(item => item.learner_id === selected.learner.id && item.course_id === selected.course.id ? { ...item, certificate_status: 'revoked' } : item),
      },
    }))
    setConfirmRevoke(false)
    setNotice('Certificate revoked in this preview.')
  }

  function exportCsv() {
    setExporting(true)
    const lines = [
      'learner_name,course_title,serial_number,issued_local_date',
      ...matching.map(item => [item.learner.name, item.course.title, item.serial_number, item.issued_local_date].map(escapeCsv).join(',')),
    ]
    const url = URL.createObjectURL(new Blob([lines.join('\r\n') + '\r\n'], { type: 'text/csv;charset=utf-8' }))
    const link = document.createElement('a')
    link.href = url
    link.download = `certificates-${tenant.id}.csv`
    link.click()
    setTimeout(() => { URL.revokeObjectURL(url); setExporting(false) }, 200)
  }

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">C</div><div><strong>Certificate<br />Console</strong><small>Admin workspace</small></div></div>
      <div className="nav-caption">WORKSPACE</div>
      <button className={`nav-item ${view === 'certificates' ? 'active' : ''}`} onClick={() => setView('certificates')}><span>▦</span> Certificates</button>
      <button className={`nav-item ${view === 'courses' ? 'active' : ''}`} onClick={() => setView('courses')}><span>☷</span> Course review</button>
      <div className="sidebar-bottom"><span className="preview-dot" /> Sample-data wireframe<br /><small>Changes reset on refresh</small></div>
    </aside>

    <main className="main">
      <header className="topbar"><div className="breadcrumb">Workspace <span>/</span> {view === 'certificates' ? 'Certificates' : 'Course review'}</div><div className="actor-control"><label htmlFor="actor">Viewing as</label><select id="actor" value={actorEmail} onChange={event => switchActor(event.target.value)}>{actors.map(item => <option key={item.email} value={item.email}>{item.email}</option>)}</select><div className="avatar">{actorEmail[0].toUpperCase()}</div></div></header>
      <div className="content">
        <div className="page-intro"><div><div className="eyebrow">{tenant.name.toUpperCase()} TENANT · {tenant.time_zone}</div><h1>{view === 'certificates' ? 'Certificates' : 'Course completion review'}</h1><p>{view === 'certificates' ? 'Find, review, export, and revoke issued certificates.' : 'Check learner completion before issuing certificates.'}</p></div>{view === 'certificates' && <button className="button primary" onClick={exportCsv} disabled={exporting}>{exporting ? 'Preparing CSV…' : '↓ Export CSV'}</button>}</div>

        {view === 'certificates' ? <>
          <section className="stats"><div><small>Total certificates</small><strong>{data.certificates.length}</strong></div><div><small>Issued</small><strong>{data.certificates.filter(item => item.status === 'issued').length}</strong></div><div><small>Revoked</small><strong>{data.certificates.filter(item => item.status === 'revoked').length}</strong></div></section>
          <section className="panel"><div className="panel-heading"><div><h2>Certificate list</h2><p>Search this tenant’s records and open a row for details.</p></div></div>
            <div className="toolbar"><label className="search-field"><span>⌕</span><input aria-label="Search learner or serial" placeholder="Search learner or serial…" value={search} onChange={event => { setSearch(event.target.value); setPage(1) }} /></label><div className="toolbar-right"><label>Sort by <select aria-label="Sort by" value={sortBy} onChange={event => { setSortBy(event.target.value); setPage(1) }}>{sortOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><button className="button subtle" onClick={() => setSortDir(value => value === 'asc' ? 'desc' : 'asc')} aria-label={`Sort ${sortDir === 'asc' ? 'descending' : 'ascending'}`}>{sortDir === 'asc' ? '↑ Asc' : '↓ Desc'}</button></div></div>
            <div className="table-scroll"><table><thead><tr><th>Learner</th><th>Course</th><th>Serial number</th><th>Issued locally</th><th>Status</th><th></th></tr></thead><tbody>{shown.map(item => <tr key={item.id} onClick={() => { setSelectedId(item.id); setNotice('') }}><td className="strong-cell">{item.learner.name}</td><td>{item.course.title}</td><td className="mono">{item.serial_number}</td><td>{localTime(item.issued_at_local)}</td><td><Badge value={item.status} /></td><td className="arrow">→</td></tr>)}</tbody></table>{shown.length === 0 && <div className="empty"><strong>No certificates found</strong><p>Try another learner name or serial number.</p></div>}</div>
            <div className="pagination"><span>{matching.length === 0 ? '0' : (page - 1) * pageSize + 1}–{Math.min(page * pageSize, matching.length)} of {matching.length}</span><div><button disabled={page <= 1} onClick={() => setPage(value => value - 1)}>← Previous</button><span>Page {page} of {certificatePages || 1}</span><button disabled={page >= certificatePages} onClick={() => setPage(value => value + 1)}>Next →</button></div></div>
          </section>
        </> : <>
          <section className="panel"><div className="panel-heading"><div><h2>Choose a course</h2><p>Review completion and certificate state for each learner.</p></div></div><div className="course-picker"><label htmlFor="course">Course</label><select id="course" value={courseId} onChange={event => { setCourseId(event.target.value); setEnrollmentPage(1); setOutcome(null) }}>{data.courses.map(course => <option key={course.id} value={course.id}>{course.title}</option>)}</select><span>{courseEnrollments.length} learners enrolled</span></div></section>
          <section className="panel"><div className="panel-heading"><div><h2>Enrollments</h2><p>Completed learners with no certificate are eligible.</p></div><button className="button primary" onClick={issueCertificates}>Issue eligible certificates</button></div><div className="table-scroll"><table><thead><tr><th>Learner</th><th>Completion</th><th>Certificate</th><th>Eligibility</th></tr></thead><tbody>{shownEnrollments.map(row => <tr key={row.learner_id}><td className="strong-cell">{row.learner_name}</td><td><Badge value={row.completion_status} /></td><td><Badge value={row.certificate_status} /></td><td>{row.completion_status === 'incomplete' ? 'Incomplete' : row.certificate_status !== 'none' ? 'Already certified' : 'Ready to issue'}</td></tr>)}</tbody></table></div><div className="pagination"><span>{courseEnrollments.length} learners</span><div><button disabled={enrollmentPage <= 1} onClick={() => setEnrollmentPage(value => value - 1)}>← Previous</button><span>Page {enrollmentPage} of {enrollmentPages || 1}</span><button disabled={enrollmentPage >= enrollmentPages} onClick={() => setEnrollmentPage(value => value + 1)}>Next →</button></div></div></section>
          {outcome && <section className="panel outcome-panel"><div className="panel-heading"><div><div className="eyebrow">OPERATION COMPLETED</div><h2>Issue results</h2><p>Operation {outcome.operation_id}</p></div><div className="result-counts"><span>{outcome.summary.issued} issued</span><span>{outcome.summary.skipped} skipped</span><span>{outcome.summary.failed} failed</span></div></div><div className="table-scroll"><table><thead><tr><th>Learner</th><th>Result</th><th>Reason</th><th>Serial number</th></tr></thead><tbody>{outcome.outcomes.map(row => <tr key={row.learner_id}><td className="strong-cell">{row.learner_name}</td><td><Badge value={row.result} /></td><td>{row.reason?.replaceAll('_', ' ') || '—'}</td><td className="mono">{row.serial_number || '—'}</td></tr>)}</tbody></table></div></section>}
        </>}

